object WidgetHelper {
    private const val PREFS_NAME = "SynthesiscoWidgetPrefs"
    private const val KEY_OPACITY_PERCENT = "opacity_percent_"
    private const val DEFAULT_OPACITY_PERCENT = 65

    fun saveOpacityPercent(context: Context, widgetId: Int, percent: Int) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        prefs.edit()
            .putInt(KEY_OPACITY_PERCENT + widgetId, percent)
            .putInt(KEY_OPACITY_PERCENT + "global", percent)
            .apply()
    }

    fun getOpacityPercent(context: Context, widgetId: Int): Int {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val globalDefault = prefs.getInt(KEY_OPACITY_PERCENT + "global", DEFAULT_OPACITY_PERCENT)
        return prefs.getInt(KEY_OPACITY_PERCENT + widgetId, globalDefault)
    }

    fun getPhraseForToday(context: Context): String {
        return try {
            val jsonStr = context.assets.open("frases.json").bufferedReader().use { it.readText() }
            val array = JSONArray(jsonStr)
            val dayOfYear = Calendar.getInstance().get(Calendar.DAY_OF_YEAR) - 1
            val index = dayOfYear.coerceAtLeast(0) % array.length()
            array.getString(index)
        } catch (e: Exception) {
            "That's when champions are made."
        }
    }

    fun getMidnightElapsedRealtimeBase(): Long {
        val now = System.currentTimeMillis()
        val midnight = Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
            add(Calendar.DAY_OF_YEAR, 1)
        }.timeInMillis
        val millisUntilMidnight = (midnight - now).coerceAtLeast(0L)
        return SystemClock.elapsedRealtime() + millisUntilMidnight
    }

    /**
     * Genera un Bitmap de vidrio esmerilado (Glassmorphism) realista con:
     * - Refracción translúcida lechosa/cristalina (como vidrio esmerilado sobre el fondo)
     * - Brillo especular diagonal suave
     * - Micro-textura esmerilada sutil
     * - Borde luminoso de cristal biselado con esquinas de 20dp
     */
    fun createFrostedGlassBitmap(widthPx: Int, heightPx: Int, cornerRadiusPx: Float, opacityPercent: Int): Bitmap {
        val w = widthPx.coerceIn(200, 1200)
        val h = heightPx.coerceIn(200, 1200)
        val bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        if (opacityPercent <= 0) return bitmap

        val canvas = Canvas(bitmap)
        val factor = (opacityPercent.coerceIn(0, 100) / 100f)

        val rect = RectF(2f, 2f, w - 2f, h - 2f)
        val clipPath = Path().apply {
            addRoundRect(rect, cornerRadiusPx, cornerRadiusPx, Path.Direction.CW)
        }

        canvas.save()
        canvas.clipPath(clipPath)

        // 1. Capa base de cristal esmerilado (gradiente diagonal helado/lechoso)
        val aTop = (210 * factor).toInt().coerceIn(0, 255)
        val aMid = (165 * factor).toInt().coerceIn(0, 255)
        val aBot = (185 * factor).toInt().coerceIn(0, 255)

        val basePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            shader = LinearGradient(
                0f, 0f, w.toFloat(), h.toFloat(),
                intArrayOf(
                    Color.argb(aTop, 195, 212, 228),
                    Color.argb(aMid, 130, 152, 172),
                    Color.argb(aBot, 92, 114, 135)
                ),
                floatArrayOf(0f, 0.52f, 1f),
                Shader.TileMode.CLAMP
            )
        }
        canvas.drawRect(rect, basePaint)

        // 2. Resplandor difuso central-superior para simular dispersión de luz en vidrio
        val glowAlpha = (95 * factor).toInt().coerceIn(0, 255)
        val glowPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            shader = RadialGradient(
                w * 0.3f, h * 0.22f, max(w, h) * 0.75f,
                intArrayOf(
                    Color.argb(glowAlpha, 255, 255, 255),
                    Color.argb((glowAlpha * 0.35f).toInt(), 230, 242, 255),
                    Color.argb(0, 255, 255, 255)
                ),
                floatArrayOf(0f, 0.5f, 1f),
                Shader.TileMode.CLAMP
            )
        }
        canvas.drawRect(rect, glowPaint)

        // 3. Reflejo oblicuo de cristal en la parte superior
        val sheenAlpha = (70 * factor).toInt().coerceIn(0, 255)
        val sheenPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            shader = LinearGradient(
                0f, 0f, 0f, h * 0.55f,
                Color.argb(sheenAlpha, 255, 255, 255),
                Color.argb(0, 255, 255, 255),
                Shader.TileMode.CLAMP
            )
        }
        canvas.drawRect(0f, 0f, w.toFloat(), h * 0.55f, sheenPaint)

        // 4. Micro-grano esmerilado sutil para textura física de vidrio
        val noisePaint = Paint()
        val rng = Random(42L)
        val noiseAlpha = (18 * factor).toInt().coerceIn(0, 255)
        if (noiseAlpha > 2) {
            val step = 3
            var y = 0
            while (y < h) {
                var x = 0
                while (x < w) {
                    val isLight = rng.nextBoolean()
                    noisePaint.color = if (isLight) {
                        Color.argb(noiseAlpha, 255, 255, 255)
                    } else {
                        Color.argb((noiseAlpha * 0.7f).toInt(), 20, 35, 50)
                    }
                    canvas.drawPoint(x.toFloat(), y.toFloat(), noisePaint)
                    x += step
                }
                y += step
            }
        }

        canvas.restore()

        // 5. Borde especular de cristal (más brillante arriba/izquierda, suave abajo/derecha)
        val borderAlphaTop = (230 * min(1f, factor * 1.25f)).toInt().coerceIn(0, 255)
        val borderAlphaBot = (110 * min(1f, factor * 1.25f)).toInt().coerceIn(0, 255)
        val borderWidth = max(2f, w * 0.0045f)

        val borderPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = borderWidth
            shader = LinearGradient(
                0f, 0f, w.toFloat(), h.toFloat(),
                intArrayOf(
                    Color.argb(borderAlphaTop, 255, 255, 255),
                    Color.argb((borderAlphaTop * 0.65f).toInt(), 235, 245, 255),
                    Color.argb(borderAlphaBot, 255, 255, 255)
                ),
                floatArrayOf(0f, 0.5f, 1f),
                Shader.TileMode.CLAMP
            )
        }
        val borderRect = RectF(
            borderWidth / 2f + 1f,
            borderWidth / 2f + 1f,
            w - borderWidth / 2f - 1f,
            h - borderWidth / 2f - 1f
        )
        canvas.drawRoundRect(borderRect, cornerRadiusPx, cornerRadiusPx, borderPaint)

        return bitmap
    }

    /**
     * Divide la frase únicamente por espacios (NUNCA corta una palabra a la mitad como "ch-ampions")
     * y calcula el tamaño más grande e imponente posible donde cada palabra entera cabe en su línea
     * y todas las líneas caben verticalmente.
     */
    private fun wrapWordsWhole(words: List<String>, paint: TextPaint, maxWidth: Float): List<String>? {
        val lines = mutableListOf<String>()
        var currentLine = ""

        for (word in words) {
            // Si una sola palabra es más ancha que el renglón disponible, este tamaño de letra no sirve
            if (paint.measureText(word) > maxWidth) {
                return null
            }
            val testLine = if (currentLine.isEmpty()) word else "$currentLine $word"
            if (paint.measureText(testLine) <= maxWidth) {
                currentLine = testLine
            } else {
                if (currentLine.isNotEmpty()) lines.add(currentLine)
                currentLine = word
            }
        }
        if (currentLine.isNotEmpty()) {
            lines.add(currentLine)
        }
        return lines
    }

    /**
     * Renderiza la frase con tipografía extra-gruesa e imponente (Black + Stroke de engrosamiento),
     * garantizando 0 palabras cortadas tanto en 2x2 como en 4x2.
     */
    fun createPhraseBitmap(phrase: String, widthPx: Int, heightPx: Int): Bitmap {
        val w = widthPx.coerceIn(220, 1400)
        val h = heightPx.coerceIn(140, 1000)
        val bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)

        val words = phrase.trim().split(Regex("\s+")).filter { it.isNotEmpty() }
        if (words.isEmpty()) return bitmap

        val baseTypeface = Typeface.create("sans-serif-black", Typeface.BOLD)
        val paint = TextPaint(Paint.ANTI_ALIAS_FLAG or Paint.SUBPIXEL_TEXT_FLAG).apply {
            typeface = baseTypeface
            isFakeBoldText = true
            letterSpacing = -0.015f
        }

        val usableWidth = w * 0.90f
        val usableHeight = h * 0.88f

        var bestSizePx = 24f
        var bestLines: List<String> = listOf(phrase)

        val maxCandidatePx = min(w, h) * 0.42f
        val minCandidatePx = 14f

        var testPx = maxCandidatePx
        while (testPx >= minCandidatePx) {
            paint.textSize = testPx
            // Engrosamiento extra (stroke) considerado en la medición
            val extraStroke = testPx * 0.042f
            paint.strokeWidth = extraStroke

            val candidateLines = wrapWordsWhole(words, paint, usableWidth - extraStroke * 2f)
            if (candidateLines != null) {
                val lineHeight = testPx * 1.14f
                val totalHeight = candidateLines.size * lineHeight
                if (totalHeight <= usableHeight) {
                    bestSizePx = testPx
                    bestLines = candidateLines
                    break
                }
            }
            testPx -= 1.5f
        }

        // Configurar pinceles finales para efecto imponente y grueso
        val strokeThickness = bestSizePx * 0.042f
        val lineHeight = bestSizePx * 1.14f
        val totalBlockHeight = bestLines.size * lineHeight

        val fontMetrics = paint.apply { textSize = bestSizePx }.fontMetrics
        val firstBaselineY = (h - totalBlockHeight) / 2f - fontMetrics.ascent * 0.88f

        // 1. Pincel de sombra profunda para contraste total sobre vidrio
        val shadowPaint = TextPaint(paint).apply {
            textSize = bestSizePx
            style = Paint.Style.FILL_AND_STROKE
            strokeWidth = strokeThickness
            strokeJoin = Paint.Join.ROUND
            strokeCap = Paint.Cap.ROUND
            color = Color.WHITE
            setShadowLayer(bestSizePx * 0.22f, 0f, bestSizePx * 0.08f, Color.argb(185, 0, 0, 0))
        }

        // 2. Pincel de relleno blanco puro ultra-grueso
        val fillPaint = TextPaint(paint).apply {
            textSize = bestSizePx
            style = Paint.Style.FILL_AND_STROKE
            strokeWidth = strokeThickness
            strokeJoin = Paint.Join.ROUND
            strokeCap = Paint.Cap.ROUND
            color = Color.WHITE
        }

        for ((index, line) in bestLines.withIndex()) {
            val lineWidth = fillPaint.measureText(line)
            val x = (w - lineWidth) / 2f
            val y = firstBaselineY + index * lineHeight
            canvas.drawText(line, x, y, shadowPaint)
            canvas.drawText(line, x, y, fillPaint)
        }

        return bitmap
    }

    fun updateSingleWidget(context: Context, appWidgetManager: AppWidgetManager, widgetId: Int) {
        val views = RemoteViews(context.packageName, R.layout.widget_layout)
        val phrase = getPhraseForToday(context)

        // Determinar dimensiones reales del widget (2x2 vs 4x2 o redimensionado)
        val options: Bundle? = try {
            appWidgetManager.getAppWidgetOptions(widgetId)
        } catch (e: Exception) {
            null
        }

        val providerInfo = try {
            appWidgetManager.getAppWidgetInfo(widgetId)
        } catch (e: Exception) {
            null
        }
        val isSquare = providerInfo?.provider?.className?.contains("SquarePhraseWidget") == true

        val defaultWidthDp = if (isSquare) 145 else 290
        val defaultHeightDp = 145

        val minWidthDp = options?.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH, 0)
            ?.takeIf { it > 40 } ?: defaultWidthDp
        val minHeightDp = options?.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT, 0)
            ?.takeIf { it > 40 } ?: defaultHeightDp

        val density = context.resources.displayMetrics.density.coerceIn(1.5f, 3.5f)
        val cardWidthPx = (minWidthDp * density).toInt().coerceIn(260, 1200)
        val cardHeightPx = (minHeightDp * density).toInt().coerceIn(220, 900)
        val cornerRadiusPx = 20f * density

        val percent = getOpacityPercent(context, widgetId).coerceIn(0, 100)

        // Generar vidrio esmerilado y tipografía imponente sin palabras cortadas
        val glassBitmap = createFrostedGlassBitmap(cardWidthPx, cardHeightPx, cornerRadiusPx, percent)
        val phraseAreaWidthPx = (cardWidthPx - (20f * density)).toInt().coerceAtLeast(200)
        val phraseAreaHeightPx = (cardHeightPx - (36f * density)).toInt().coerceAtLeast(140)
        val phraseBitmap = createPhraseBitmap(phrase, phraseAreaWidthPx, phraseAreaHeightPx)

        views.setImageViewBitmap(R.id.widget_bg_image, glassBitmap)
        views.setInt(R.id.widget_bg_image, "setImageAlpha", 255)
        views.setImageViewBitmap(R.id.widget_phrase_image, phraseBitmap)

        // Cronómetro regresivo hasta medianoche
        val targetBase = getMidnightElapsedRealtimeBase()
        views.setChronometerCountDown(R.id.widget_countdown, true)
        views.setChronometer(R.id.widget_countdown, targetBase, null, true)

        // Tocar el widget permite reajustar el efecto vidrio cuando quieras
        val configIntent = Intent(context, WidgetConfigActivity::class.java).apply {
            putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId)
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val configPendingIntent = PendingIntent.getActivity(
            context,
            widgetId,
            configIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        views.setOnClickPendingIntent(R.id.widget_root, configPendingIntent)

        appWidgetManager.updateAppWidget(widgetId, views)
    }

    fun updateAllWidgets(context: Context) {
        val manager = AppWidgetManager.getInstance(context)
        val squareIds = manager.getAppWidgetIds(ComponentName(context, SquarePhraseWidget::class.java))
        val rectIds = manager.getAppWidgetIds(ComponentName(context, RectanglePhraseWidget::class.java))
        for (id in squareIds) updateSingleWidget(context, manager, id)
        for (id in rectIds) updateSingleWidget(context, manager, id)
    }

    fun scheduleMidnightUpdate(context: Context) {
        val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
        val intent = Intent(context, SquarePhraseWidget::class.java).apply {
            action = "com.synthesisco.frases.ACTION_MIDNIGHT_UPDATE"
        }
        val pendingIntent = PendingIntent.getBroadcast(
            context,
            999,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        val midnight = Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 1)
            set(Calendar.MILLISECOND, 0)
            add(Calendar.DAY_OF_YEAR, 1)
        }
        alarmManager.setInexactRepeating(
            AlarmManager.RTC,
            midnight.timeInMillis,
            AlarmManager.INTERVAL_DAY,
            pendingIntent
        )
    }
}

package com.synthesisco.frases

import android.appwidget.AppWidgetManager
import android.appwidget.AppWidgetProvider
import android.content.Context
import android.content.Intent
import android.os.Bundle

class SquarePhraseWidget : AppWidgetProvider() {
    override fun onUpdate(context: Context, appWidgetManager: AppWidgetManager, appWidgetIds: IntArray) {
        for (id in appWidgetIds) {
            WidgetHelper.updateSingleWidget(context, appWidgetManager, id)
        }
        WidgetHelper.scheduleMidnightUpdate(context)
    }

    override fun onAppWidgetOptionsChanged(
        context: Context,
        appWidgetManager: AppWidgetManager,
        appWidgetId: Int,
        newOptions: Bundle
    ) {
        super.onAppWidgetOptionsChanged(context, appWidgetManager, appWidgetId, newOptions)
        WidgetHelper.updateSingleWidget(context, appWidgetManager, appWidgetId)
    }

    override fun onReceive(context: Context, intent: Intent) {
        super.onReceive(context, intent)
        if (intent.action == "com.synthesisco.frases.ACTION_MIDNIGHT_UPDATE") {
            WidgetHelper.updateAllWidgets(context)
        }
    }
}

package com.synthesisco.frases

import android.appwidget.AppWidgetManager
